// Paste this whole file into the Supabase dashboard as the `plops` Edge Function.

// ---- validate.ts ----
// Input validation for the plops Edge Function. Pure TypeScript (no Deno/Node APIs) so it
// can be unit-tested from Vitest and type-checked by Deno.

export const CATEGORIES = ['gas_station', 'travel_center', 'rest_area'] as const;
export const CLEANLINESS = ['dirty', 'okay', 'very_clean', 'unknown'] as const;
export const STALL_PRIVACY = ['gaps', 'full_doors', 'single_user', 'unknown'] as const;
export const KEY_REQUIRED = ['yes', 'no', 'unknown'] as const;
export const FOOD = ['none', 'snacks', 'hot_food', 'unknown'] as const;
export const RESTROOM = ['mens', 'womens', 'all_gender', 'unspecified'] as const;
export const REPORT_REASONS = ['fake_or_duplicate', 'closed_or_not_public', 'wrong_location', 'spam_or_abuse', 'personal_info', 'other'] as const;
export const VOTES = ['agree', 'disagree', 'none'] as const;

export const LIMITS = { name: 80, address: 200, comment: 280, details: 500 } as const;

export class ValidationError extends Error {
  field: string;
  constructor(field: string, message: string) {
    super(message);
    this.field = field;
  }
}

type Obj = Record<string, unknown>;

const TOKEN_RE = /^[A-Za-z0-9_-]{43}$/;
const UUID_RE = /^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/i;
const DATE_RE = /^\d{4}-\d{2}-\d{2}$/;

/** Collapse whitespace and strip control characters. Returns null for blank input. */
export function cleanText(v: unknown, field: string, max: number, required = false, min = 1): string | null {
  if (v === undefined || v === null || v === '') {
    if (required) throw new ValidationError(field, `${field} is required.`);
    return null;
  }
  if (typeof v !== 'string') throw new ValidationError(field, `${field} must be text.`);
  // eslint-disable-next-line no-control-regex
  const s = v.replace(/[\u0000-\u001f\u007f\s]+/g, ' ').trim();
  if (!s) {
    if (required) throw new ValidationError(field, `${field} is required.`);
    return null;
  }
  if (s.length > max) throw new ValidationError(field, `${field} must be ${max} characters or fewer.`);
  if (s.length < min) throw new ValidationError(field, `${field} must be at least ${min} characters.`);
  return s;
}

function oneOf<T extends readonly string[]>(v: unknown, allowed: T, field: string, fallback?: T[number]): T[number] {
  if ((v === undefined || v === null) && fallback !== undefined) return fallback;
  if (typeof v !== 'string' || !(allowed as readonly string[]).includes(v)) {
    throw new ValidationError(field, `${field} must be one of: ${allowed.join(', ')}.`);
  }
  return v as T[number];
}

export function token(v: unknown): string {
  if (typeof v !== 'string' || !TOKEN_RE.test(v)) throw new ValidationError('token', 'Missing or malformed browser token.');
  return v;
}

export function uuid(v: unknown, field: string): string {
  if (typeof v !== 'string' || !UUID_RE.test(v)) throw new ValidationError(field, `${field} must be an id.`);
  return v.toLowerCase();
}

function isoDay(d: Date) {
  return d.toISOString().slice(0, 10);
}

export function visitDate(v: unknown, now: Date = new Date()): string {
  if (typeof v !== 'string' || !DATE_RE.test(v)) throw new ValidationError('visit_date', 'Visit date must be YYYY-MM-DD.');
  const d = new Date(`${v}T00:00:00Z`);
  if (Number.isNaN(d.getTime()) || isoDay(d) !== v) throw new ValidationError('visit_date', 'Visit date is not a real date.');
  const max = new Date(now.getTime() + 864e5); // allow one day of timezone slack
  const min = new Date(now.getTime() - 730 * 864e5);
  if (d > max) throw new ValidationError('visit_date', 'Visit date cannot be in the future.');
  if (d < min) throw new ValidationError('visit_date', 'Visit date must be within the last two years.');
  return v;
}

export function plopRating(v: unknown): number {
  if (typeof v !== 'number' || !Number.isInteger(v) || v < 1 || v > 5) {
    throw new ValidationError('rating', 'Rating must be a whole number of plops from 1 to 5.');
  }
  return v;
}

export interface RatingFields {
  rating: number;
  cleanliness: string;
  stall_privacy: string;
  key_required: string;
  food: string;
  restroom: string;
  comment: string | null;
  visit_date: string;
}

export function ratingFields(b: Obj, now?: Date): RatingFields {
  return {
    rating: plopRating(b.rating),
    cleanliness: oneOf(b.cleanliness, CLEANLINESS, 'cleanliness', 'unknown'),
    stall_privacy: oneOf(b.stall_privacy, STALL_PRIVACY, 'stall_privacy', 'unknown'),
    key_required: oneOf(b.key_required, KEY_REQUIRED, 'key_required', 'unknown'),
    food: oneOf(b.food, FOOD, 'food', 'unknown'),
    restroom: oneOf(b.restroom, RESTROOM, 'restroom', 'unspecified'),
    comment: cleanText(b.comment, 'comment', LIMITS.comment),
    visit_date: visitDate(b.visit_date, now),
  };
}

export function stopFields(b: Obj) {
  const lat = b.lat, lng = b.lng;
  if (typeof lat !== 'number' || !Number.isFinite(lat) || lat < -90 || lat > 90) throw new ValidationError('lat', 'Latitude is out of range.');
  if (typeof lng !== 'number' || !Number.isFinite(lng) || lng < -180 || lng > 180) throw new ValidationError('lng', 'Longitude is out of range.');
  return {
    name: cleanText(b.name, 'name', LIMITS.name, true, 2)!,
    category: oneOf(b.category, CATEGORIES, 'category'),
    address: cleanText(b.address, 'address', LIMITS.address, true, 3)!,
    lat,
    lng,
    confirm_distinct: b.confirm_distinct === true,
  };
}

export function voteValue(v: unknown) {
  return oneOf(v, VOTES, 'vote');
}

export function reportFields(b: Obj) {
  return {
    stop_id: uuid(b.stop_id, 'stop_id'),
    rating_id: b.rating_id == null ? null : uuid(b.rating_id, 'rating_id'),
    reason: oneOf(b.reason, REPORT_REASONS, 'reason'),
    details: cleanText(b.details, 'details', LIMITS.details),
  };
}

// ---- core.ts ----
// Request handling for the `plops` Edge Function. Runtime-agnostic: dependencies (database
// RPC, challenge verification, secret) are injected so this file runs under Deno in
// production and under Node/Vitest in tests.


export type Action = 'create_stop' | 'rate' | 'vote' | 'report' | 'me';

export class RpcError extends Error {
  status: number;
  code: string;
  constructor(status: number, code: string, message: string) {
    super(message);
    this.status = status;
    this.code = code;
  }
}

export interface Deps {
  /** Calls a Postgres function as service_role and returns its JSON result. */
  rpc: (fn: string, args: Record<string, unknown>) => Promise<unknown>;
  /** Verifies a challenge token server-side. Returns true when valid for the expected action. */
  verifyChallenge: (token: string, expectedAction: string) => Promise<boolean>;
  /** Secret used to derive keyed hashes. Never leaves the backend. */
  hashSecret: string;
  allowedOrigins: string[];
  /** When false (local development only), challenge verification is skipped. */
  challengeRequired: boolean;
  now?: () => Date;
  log?: (msg: string) => void;
}

/** Per-action limits. Each write is checked against the browser identity AND the network bucket. */
export const RATE_LIMITS: Record<Action, { identity: [number, number]; network: [number, number] }> = {
  create_stop: { identity: [5, 86_400], network: [15, 86_400] },
  rate: { identity: [30, 3_600], network: [60, 3_600] },
  vote: { identity: [60, 3_600], network: [150, 3_600] },
  report: { identity: [10, 86_400], network: [30, 86_400] },
  me: { identity: [600, 3_600], network: [1_200, 3_600] },
};

const CHALLENGED: ReadonlySet<Action> = new Set(['create_stop', 'rate', 'vote', 'report']);
const MAX_BODY = 8 * 1024;

const CONFLICT_CODES = new Set(['duplicate', 'possible_duplicate', 'own_original', 'rating_removed', 'vote_removed', 'no_original', 'stop_closed']);

const enc = new TextEncoder();

export async function hmacHex(secret: string, message: string): Promise<string> {
  const key = await crypto.subtle.importKey('raw', enc.encode(secret), { name: 'HMAC', hash: 'SHA-256' }, false, ['sign']);
  const sig = new Uint8Array(await crypto.subtle.sign('HMAC', key, enc.encode(message)));
  return Array.from(sig, (b) => b.toString(16).padStart(2, '0')).join('');
}

/** The pseudonymous identity stored in the database: HMAC of the browser token. */
export const identityHash = (secret: string, token: string) => hmacHex(secret, `identity:v1:${token}`);

/**
 * Transient network bucket for rate limiting. Keyed and salted with the UTC day so buckets
 * cannot be linked across days or reversed to an IP address without the secret.
 */
export const networkBucket = (secret: string, ip: string, now: Date) =>
  hmacHex(secret, `network:v1:${now.toISOString().slice(0, 10)}:${ip}`);

export function clientIp(req: Request): string {
  const xff = req.headers.get('x-forwarded-for');
  if (xff) return xff.split(',')[0].trim();
  return req.headers.get('cf-connecting-ip') ?? req.headers.get('x-real-ip') ?? 'unknown';
}

function corsHeaders(origin: string | null): Record<string, string> {
  const h: Record<string, string> = {
    'Content-Type': 'application/json; charset=utf-8',
    'Cache-Control': 'no-store',
    'X-Content-Type-Options': 'nosniff',
    Vary: 'Origin',
  };
  if (origin) {
    h['Access-Control-Allow-Origin'] = origin;
    h['Access-Control-Allow-Methods'] = 'POST, OPTIONS';
    h['Access-Control-Allow-Headers'] = 'content-type, apikey, authorization, x-client-info';
    h['Access-Control-Max-Age'] = '600';
  }
  return h;
}

function json(status: number, body: unknown, origin: string | null) {
  return new Response(JSON.stringify(body), { status, headers: corsHeaders(origin) });
}

function fail(status: number, code: string, message: string, origin: string | null, extra: Record<string, unknown> = {}) {
  return json(status, { ok: false, code, message, ...extra }, origin);
}

function originAllowed(origin: string, allowed: string[]) {
  return allowed.includes(origin);
}

export async function handle(req: Request, deps: Deps): Promise<Response> {
  const origin = req.headers.get('origin');
  if (origin && !originAllowed(origin, deps.allowedOrigins)) {
    return new Response(JSON.stringify({ ok: false, code: 'origin_not_allowed', message: 'This origin may not write to Playotic Plops.' }), {
      status: 403,
      headers: { 'Content-Type': 'application/json' },
    });
  }
  const allowOrigin = origin ?? null;

  if (req.method === 'OPTIONS') return new Response(null, { status: 204, headers: corsHeaders(allowOrigin) });
  if (req.method !== 'POST') return fail(405, 'method_not_allowed', 'Use POST.', allowOrigin);

  const raw = await req.text();
  if (raw.length > MAX_BODY) return fail(413, 'too_large', 'Request is too large.', allowOrigin);
  let body: Record<string, unknown>;
  try {
    const parsed = JSON.parse(raw);
    if (!parsed || typeof parsed !== 'object' || Array.isArray(parsed)) throw new Error('not an object');
    body = parsed;
  } catch {
    return fail(400, 'bad_json', 'Request body must be a JSON object.', allowOrigin);
  }

  const action = body.action as Action;
  if (!(action in RATE_LIMITS)) return fail(400, 'unknown_action', 'Unknown action.', allowOrigin);

  const now = deps.now?.() ?? new Date();
  try {
    const browserToken = token(body.token);
    // Validate everything before spending a challenge or a rate-limit slot.
    const payload = parsePayload(action, body, now);

    if (CHALLENGED.has(action) && deps.challengeRequired) {
      const ch = body.challenge;
      if (typeof ch !== 'string' || ch.length < 10 || ch.length > 2048) {
        return fail(403, 'challenge_required', 'Please complete the quick check and try again.', allowOrigin);
      }
      if (!(await deps.verifyChallenge(ch, action))) {
        return fail(403, 'challenge_failed', 'The quick check did not pass. Please try again.', allowOrigin);
      }
    }

    const who = await identityHash(deps.hashSecret, browserToken);
    const net = await networkBucket(deps.hashSecret, clientIp(req), now);
    const lim = RATE_LIMITS[action];
    const okNet = await deps.rpc('api_rate_limit', { p_bucket: net, p_action: `${action}:net`, p_max: lim.network[0], p_window_seconds: lim.network[1] });
    const okId = okNet && (await deps.rpc('api_rate_limit', { p_bucket: who, p_action: `${action}:id`, p_max: lim.identity[0], p_window_seconds: lim.identity[1] }));
    if (!okNet || !okId) {
      return fail(429, 'rate_limited', 'Too many submissions for now. Please try again later.', allowOrigin);
    }

    const result = (await dispatch(action, who, payload, deps)) as { ok?: boolean; code?: string; message?: string };
    if (result && result.ok === false) {
      const status = result.code === 'not_found' ? 404 : result.code && CONFLICT_CODES.has(result.code) ? 409 : 400;
      return json(status, result, allowOrigin);
    }
    return json(200, action === 'me' ? { ok: true, state: result } : result, allowOrigin);
  } catch (e) {
    if (e instanceof ValidationError) return fail(400, 'invalid', e.message, allowOrigin, { field: e.field });
    if (e instanceof RpcError && ['22023', '23514', '22P02', '22007', '22008', '23502'].includes(e.code)) {
      return fail(400, 'invalid', 'Some of the submitted values were not accepted.', allowOrigin);
    }
    deps.log?.(`plops error: ${e instanceof Error ? e.message : String(e)}`);
    return fail(500, 'server_error', 'Something went wrong on our side. Please try again.', allowOrigin);
  }
}

type Payload = Record<string, unknown>;

function parsePayload(action: Action, b: Record<string, unknown>, now: Date): Payload {
  switch (action) {
    case 'create_stop':
      return { ...stopFields(b), ...ratingFields(b, now) };
    case 'rate':
      return { stop_id: uuid(b.stop_id, 'stop_id'), ...ratingFields(b, now) };
    case 'vote':
      return { stop_id: uuid(b.stop_id, 'stop_id'), vote: voteValue(b.vote) };
    case 'report':
      return reportFields(b);
    case 'me':
      return { stop_id: uuid(b.stop_id, 'stop_id') };
  }
}

function dispatch(action: Action, who: string, p: Payload, deps: Deps) {
  switch (action) {
    case 'create_stop':
      return deps.rpc('api_create_stop', {
        p_contributor: who,
        p_name: p.name, p_category: p.category, p_address: p.address, p_lat: p.lat, p_lng: p.lng,
        p_confirm_distinct: p.confirm_distinct,
        p_rating: p.rating, p_cleanliness: p.cleanliness, p_stall_privacy: p.stall_privacy,
        p_key_required: p.key_required, p_food: p.food, p_restroom: p.restroom,
        p_comment: p.comment, p_visit_date: p.visit_date,
      });
    case 'rate':
      return deps.rpc('api_submit_rating', {
        p_contributor: who, p_stop_id: p.stop_id,
        p_rating: p.rating, p_cleanliness: p.cleanliness, p_stall_privacy: p.stall_privacy,
        p_key_required: p.key_required, p_food: p.food, p_restroom: p.restroom,
        p_comment: p.comment, p_visit_date: p.visit_date,
      });
    case 'vote':
      return deps.rpc('api_set_agreement', { p_voter: who, p_stop_id: p.stop_id, p_vote: p.vote });
    case 'report':
      return deps.rpc('api_create_report', {
        p_reporter: who, p_stop_id: p.stop_id, p_rating_id: p.rating_id, p_reason: p.reason, p_details: p.details,
      });
    case 'me':
      return deps.rpc('api_my_state', { p_contributor: who, p_stop_id: p.stop_id });
  }
}

/** Cloudflare Turnstile Siteverify. Raw IPs are not forwarded (optional per Cloudflare docs). */
export function turnstileVerifier(secret: string, expectedHostnames: string[], fetchImpl: typeof fetch = fetch) {
  return async (token: string, expectedAction: string) => {
    const res = await fetchImpl('https://challenges.cloudflare.com/turnstile/v0/siteverify', {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({ secret, response: token }),
    });
    if (!res.ok) return false;
    const out = (await res.json()) as { success?: boolean; action?: string; hostname?: string };
    if (!out.success) return false;
    if (out.action && out.action !== expectedAction) return false;
    if (expectedHostnames.length && out.hostname && !expectedHostnames.includes(out.hostname)) return false;
    return true;
  };
}

/** PostgREST RPC with the service key on the apikey header (works for new secret keys and legacy JWT keys). */
export function postgrestRpc(supabaseUrl: string, serviceKey: string, fetchImpl: typeof fetch = fetch) {
  return async (fn: string, args: Record<string, unknown>) => {
    const headers: Record<string, string> = { 'Content-Type': 'application/json', apikey: serviceKey };
    if (serviceKey.startsWith('eyJ')) headers.Authorization = `Bearer ${serviceKey}`;
    const res = await fetchImpl(`${supabaseUrl.replace(/\/$/, '')}/rest/v1/rpc/${fn}`, {
      method: 'POST',
      headers,
      body: JSON.stringify(args),
    });
    const text = await res.text();
    if (!res.ok) {
      let code = String(res.status);
      let message = text;
      try {
        const j = JSON.parse(text);
        code = j.code ?? code;
        message = j.message ?? message;
      } catch { /* keep raw */ }
      throw new RpcError(res.status, code, message);
    }
    return text ? JSON.parse(text) : null;
  };
}

// ---- index.ts ----
// Supabase Edge Function entry point: `plops`.
// Deploy: supabase functions deploy plops --no-verify-jwt   (also set in supabase/config.toml)
//
// Required secrets (supabase secrets set ...):
//   PLOPS_HASH_SECRET      long random string; keys identity hashes and rate-limit buckets
//   ALLOWED_ORIGINS        comma-separated, e.g. https://you.github.io,http://localhost:5173
//   TURNSTILE_SECRET_KEY   Cloudflare Turnstile secret key
// Optional:
//   TURNSTILE_HOSTNAMES    comma-separated hostnames the challenge must have been solved on
//   CHALLENGE_MODE=off     local development only; disables challenge verification
// Provided by Supabase automatically: SUPABASE_URL, SUPABASE_SECRET_KEYS (or legacy SUPABASE_SERVICE_ROLE_KEY)


const env = (k: string) => Deno.env.get(k)?.trim() ?? '';
const list = (k: string) => env(k).split(',').map((s) => s.trim()).filter(Boolean);

function serviceKey(): string {
  const keys = env('SUPABASE_SECRET_KEYS');
  if (keys) {
    try {
      const parsed = JSON.parse(keys) as Record<string, string>;
      const k = parsed['default'] ?? Object.values(parsed)[0];
      if (k) return k;
    } catch { /* fall through to legacy key */ }
  }
  return env('SUPABASE_SERVICE_ROLE_KEY');
}

const supabaseUrl = env('SUPABASE_URL');
const key = serviceKey();
const hashSecret = env('PLOPS_HASH_SECRET');
const turnstileSecret = env('TURNSTILE_SECRET_KEY');
const challengeOff = env('CHALLENGE_MODE') === 'off';

const misconfigured: string[] = [];
if (!supabaseUrl) misconfigured.push('SUPABASE_URL');
if (!key) misconfigured.push('SUPABASE_SECRET_KEYS');
if (hashSecret.length < 32) misconfigured.push('PLOPS_HASH_SECRET (32+ chars)');
if (!turnstileSecret && !challengeOff) misconfigured.push('TURNSTILE_SECRET_KEY');
if (!list('ALLOWED_ORIGINS').length) misconfigured.push('ALLOWED_ORIGINS');

Deno.serve((req) => {
  if (misconfigured.length) {
    console.error(`plops is missing configuration: ${misconfigured.join(', ')}`);
    return new Response(JSON.stringify({ ok: false, code: 'not_configured', message: 'Submissions are not configured on this server yet.' }), {
      status: 503,
      headers: {
        'Content-Type': 'application/json',
        'Access-Control-Allow-Origin': list('ALLOWED_ORIGINS').includes(req.headers.get('origin') ?? '') ? req.headers.get('origin')! : 'null',
      },
    });
  }
  return handle(req, {
    rpc: postgrestRpc(supabaseUrl, key),
    verifyChallenge: turnstileVerifier(turnstileSecret, list('TURNSTILE_HOSTNAMES')),
    hashSecret,
    allowedOrigins: list('ALLOWED_ORIGINS'),
    challengeRequired: !challengeOff,
    log: (m) => console.error(m),
  });
});
